// JAH demo program — One-pager
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
var sections=[["Context", "Server costs up 40% QoQ."], ["Options", "A: Reserved instances (\u221230%). B: Re-architect (\u221250%, 3 mo)."], ["Recommendation", "Option A now; B in Q1."], ["Ask", "Approve $12k for reserved capacity."]];
var report=sections.map(function(s){return "## "+s[0]+"\n"+s[1];}).join("\n\n");
console.log(report.split("\n").slice(0,6).join("\n"));
console.log("...");
check("4 sections, one page", sections.length, 4);
check("ask is concrete", /\$12k/.test(report), true);
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

